(()=>{var a=document.querySelector("#filter-input"),c=document.querySelectorAll(".activity-feed-item"),n=document.querySelectorAll(".activity-feed-item-year");a.addEventListener("input",()=>{let t=a.value.trim().toLowerCase();c.forEach(e=>{let o=e.getAttribute("data-title")?.toLowerCase()??"",r=e.getAttribute("data-tags")?.toLowerCase()??"",s=e.getAttribute("data-year")?.toLowerCase()??"";o.includes(t)||r.includes(t)||s.includes(t)?(e.style.display="",document.querySelector(`#year-${s}`).style.display=""):(e.style.display="none",document.querySelector(`#year-${s}`).style.display="none")})});})();
